      sheetIdx = 0; header = true;
      if (!data.sheets[0].rows.length) { pickView('Fila er tom.'); return; }
      guess(headsNow()); mapView(file.name);
    }
    function mapView(fname) {
      var heads = headsNow(), rows = rowsNow();
      var colOpts = function (sel) { return '<option value="-1">– ikke bruk –</option>' + heads.map(function (h, i) { return '<option value="' + i + '"' + (i === sel ? ' selected' : '') + '>' + esc(h || 'Kolonne ' + String.fromCharCode(65 + i)) + '</option>'; }).join(''); };
      var used = {}; fields.forEach(function (f) { if (map[f.key] >= 0) used[map[f.key]] = 1; });
      box.innerHTML = '<h3>' + esc(opt.title || 'Importer fil') + ' <small>· ' + esc(fname) + '</small></h3>'
        + '<div class="fki-row">'
        + (data.sheets.length > 1 ? '<label>Ark <select data-sheet>' + data.sheets.map(function (s, i) { return '<option value="' + i + '"' + (i === sheetIdx ? ' selected' : '') + '>' + esc(s.name) + '</option>'; }).join('') + '</select></label>' : '')
        + '<label><input type="checkbox" data-head' + (header ? ' checked' : '') + '> Første rad er overskrifter</label>'
        + '<small>' + rows.length + ' rader</small></div>'
        + '<div class="fki-map">' + fields.map(function (f) { return '<label>' + esc(f.label) + (f.required ? ' *' : '') + '<select data-f="' + f.key + '">' + colOpts(map[f.key]) + '</select></label>'; }).join('') + '</div>'
        + '<div class="fki-prev"><table><thead><tr>' + heads.map(function (h, i) { return '<th class="' + (used[i] ? 'on' : '') + '">' + esc(h) + '</th>'; }).join('') + '</tr></thead><tbody>'
        + rows.slice(0, 12).map(function (r) { return '<tr>' + r.map(function (c, i) { return '<td class="' + (used[i] ? 'on' : '') + '">' + esc(c) + '</td>'; }).join('') + '</tr>'; }).join('')
        + '</tbody></table></div>'
        + (rows.length > 12 ? '<small>Viser 12 av ' + rows.length + ' rader.</small>' : '')
        + '<div class="fki-row" style="justify-content:space-between"><label>' + (opt.replaceLabel ? '<input type="checkbox" data-rep checked> ' + esc(opt.replaceLabel) : '') + '</label>'
        + '<div class="fki-btns"><button class="fki-btn" data-back>Annen fil</button><button class="fki-btn" data-x>Avbryt</button><button class="fki-btn fki-btn--p" data-ok>Importer ' + rows.length + ' rader</button></div></div>';
      var ok = box.querySelector('[data-ok]');
      var miss = fields.filter(function (f) { return f.required && !(map[f.key] >= 0); });
      ok.disabled = !!miss.length || !rows.length;
      box.querySelectorAll('select[data-f]').forEach(function (s) { s.addEventListener('change', function () { map[s.dataset.f] = +s.value; mapView(fname); }); });
      var sh = box.querySelector('[data-sheet]'); if (sh) sh.addEventListener('change', function () { sheetIdx = +sh.value; guess(headsNow()); mapView(fname); });
      box.querySelector('[data-head]').addEventListener('change', function (e) { header = e.target.checked; guess(headsNow()); mapView(fname); });
      box.querySelector('[data-back]').addEventListener('click', function () { pickView(); });
      box.querySelector('[data-x]').addEventListener('click', close);
      ok.addEventListener('click', function () {
        var rep = box.querySelector('[data-rep]');
        var objs = rowsNow().map(function (r) { var o = {}; fields.forEach(function (f) { o[f.key] = map[f.key] >= 0 ? (r[map[f.key]] || '') : ''; }); return o; });
        close(); opt.onApply(objs, { replace: rep ? rep.checked : true });
      });
    }
    pickView();
  }

  root.FaktiskImport = { readFile: readFile, openDialog: openDialog, parseDelimited: parseDelimited };
})(typeof window !== 'undefined' ? window : globalThis);

shared/labrador-files.js:
// Faktisk Studio — «Mine filer» + «Last opp fil» fra Labrador (delt fil)
//
// Konfigurasjonsdrevet: monterer et panel per URL-input som finnes på siden,
// med riktig filtype-filter (video/bilde). Injiserer egen CSS — pluginene
// trenger bare <script src="shared/labrador-files.js"> før main.js.
// Hopper over inputs som allerede har fått panel (eller egen implementasjon).
// Kanonisk kilde: plugins/_shared/.
//
// clickLoad: false brukes der flere inputs må fylles før lasting
// (for-og-etter trenger både før- og etter-bilde før «Hent»).

(function () {
  'use strict';
  if (!window.faktisk || !window.faktisk.labradorListFiles) return;

  const MOUNTS = [
    // Video-verktøyene (video-player, looping-video, video-hoydepunkter)
    { url: 'videoUrl',  btn: 'loadVideoBtn', accept: 'video' },
    // Parallax bildecollage + SoMe-bilde (bilde 1)
    { url: 'imgUrl',    btn: 'imgLoadUrl',   accept: 'image' },
    // SoMe-bilde: bilde 2 (delt bilde)
    { url: 'img2Url',   btn: 'img2LoadUrl',  accept: 'image' },
    // Bildemal: bakgrunn + bilde i boks
    { url: 'bgUrl',     btn: 'bgLoadUrl',    accept: 'image' },
    { url: 'shapeUrl',  btn: 'shapeLoadUrl', accept: 'image' },
    // Bilde med markering
    { url: 'urlImage',  btn: 'loadBtn',      accept: 'image' },
    // Før og etter-slider: fyll begge før lasting
    { url: 'urlBefore', btn: 'loadBtn',      accept: 'image', clickLoad: false },
    { url: 'urlAfter',  btn: 'loadBtn',      accept: 'image', clickLoad: false },
  ];

  const EXT = {
    video: /\.(mp4|mov|mpg|mpeg|m4v|webm)(\?|$)/i,
    image: /\.(png|jpe?g|gif|avif|heic|webp)(\?|$)/i,
  };
  const UPLOAD_FILTERS = {
    video: [{ name: 'Video', extensions: ['mp4', 'mov', 'mpg', 'mpeg', 'm4v'] }],
    image: [{ name: 'Bilde', extensions: ['png', 'jpg', 'jpeg', 'gif', 'avif', 'heic', 'webp'] }],
  };
  const TYPE_LABEL = { video: 'VIDEO', image: 'BILDE' };

  let cssInjected = false;
  function injectCss() {
    if (cssInjected) return;
    cssInjected = true;
    const css = document.createElement('style');
    css.textContent = `
      .labf-row { display: flex; gap: 6px; margin-top: 6px; }
      .labf-btn {
        flex: 1; background: rgba(255,255,255,0.14); color: #fff;
        border: 0; border-radius: var(--radius-input, 8px);
        font-family: var(--font-bold, inherit); font-weight: bold;
        font-size: 12px; height: 28px; padding: 0 10px; cursor: pointer;
        white-space: nowrap;
      }
      .labf-btn:hover { background: rgba(255,255,255,0.28); }
      .labf-btn:disabled { opacity: 0.4; cursor: not-allowed; }
      .labf-panel {
        background: var(--bg-input, #fff); border-radius: var(--radius-input, 8px);
        padding: 8px; max-height: 200px; overflow-y: auto;
        display: flex; flex-direction: column; gap: 4px; margin-top: 6px;
      }
      .labf-panel__status { font-size: 12px; color: #666; padding: 2px 4px; }
      .labf-panel__status button {
        background: transparent; border: 0; color: #0050FC;
        font-weight: bold; cursor: pointer; text-decoration: underline;
        font-size: 12px; padding: 0;
      }
      .labf-file {
        display: flex; align-items: center; gap: 8px;
        padding: 5px 6px; border-radius: 6px; cursor: pointer;
        font-size: 12.5px; color: var(--text-input, #222);
      }
      .labf-file:hover { background: rgba(0,0,0,0.08); }
      .labf-file__type {
        font-size: 10px; font-weight: bold; background: #0050FC; color: #fff;
        border-radius: 4px; padding: 1px 5px; flex-shrink: 0;
      }
      .labf-file__name {
        flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
        font-family: var(--font-bold, inherit); font-weight: bold;
      }
      .labf-progress {
        height: 6px; background: rgba(0,0,0,0.15); border-radius: 3px;
        overflow: hidden; margin-top: 4px; display: none;
      }
      .labf-progress__bar {
        height: 100%; width: 0; background: #0050FC; transition: width 0.3s;
      }
    `;
    document.head.appendChild(css);
  }

  const statusEl = document.getElementById('status');
  const setStatus = (msg, isError) => {
    if (!statusEl) return;
    statusEl.textContent = msg || '';
    statusEl.style.color = isError ? '#FFB4B4' : '#fff';
  };

  function mount(cfg) {
    const urlInput = document.getElementById(cfg.url);
    const loadBtn = document.getElementById(cfg.btn);
    if (!urlInput || !loadBtn) return;
    if (urlInput.dataset.labfMounted) return;
    if (cfg.url === 'videoUrl' && document.getElementById('labFilesBtn')) return; // video-sensur har egen
    urlInput.dataset.labfMounted = '1';
    injectCss();

    const anchor = urlInput.closest('.url-row') || urlInput.parentElement;
    if (!anchor || !anchor.parentElement) return;

    const row = document.createElement('div');
    row.className = 'labf-row';
    row.innerHTML =
      '<button class="labf-btn" type="button">Mine filer ▾</button>' +
      '<button class="labf-btn" type="button">Last opp fil…</button>';
    const panel = document.createElement('div');
    panel.className = 'labf-panel';
    panel.style.display = 'none';
    panel.innerHTML = '<div class="labf-panel__status"></div><div class="labf-panel__list"></div>';
    const progress = document.createElement('div');
    progress.className = 'labf-progress';
    progress.innerHTML = '<div class="labf-progress__bar"></div>';

    anchor.insertAdjacentElement('afterend', progress);
    anchor.insertAdjacentElement('afterend', panel);
    anchor.insertAdjacentElement('afterend', row);

    const [filesBtn, uploadBtn] = row.querySelectorAll('button');
    const panelStatus = panel.querySelector('.labf-panel__status');
    const panelList = panel.querySelector('.labf-panel__list');
    const progressBar = progress.querySelector('.labf-progress__bar');
    const extRe = EXT[cfg.accept] || EXT.image;

    function pick(url) {
      urlInput.value = url;
      // Noen plugins lagrer state på input-event — utløs det
      urlInput.dispatchEvent(new Event('input', { bubbles: true }));
      panel.style.display = 'none';
      if (cfg.clickLoad !== false) loadBtn.click();
      else urlInput.focus();
    }

    async function refresh() {
      panelStatus.textContent = 'Henter filer…';
      panelList.innerHTML = '';
      let res;
      try { res = await window.faktisk.labradorListFiles(); }
      catch (err) { panelStatus.textContent = 'Feil: ' + err.message; return; }

      if (!res.loggedIn) {
        panelStatus.innerHTML = 'Ikke innlogget. <button type="button">Koble til Labrador…</button>';
        panelStatus.querySelector('button').addEventListener('click', async () => {
          panelStatus.textContent = 'Logg inn i vinduet som åpnes…';
          const st = await window.faktisk.labradorConnect();
          if (st.loggedIn) refresh();
          else panelStatus.textContent = 'Fikk ikke gyldig innlogging. Prøv igjen.';
        });
        return;
      }

      const matching = res.files.filter(f => extRe.test(f.url));
      panelStatus.textContent = matching.length
        ? matching.length + ' ' + (cfg.accept === 'video' ? 'videoer' : 'bilder') + ' (nyeste først)'
        : 'Ingen ' + (cfg.accept === 'video' ? 'videoer' : 'bilder') + ' lastet opp ennå.';
      matching.slice(0, 60).forEach(f => {
        const item = document.createElement('div');
        item.className = 'labf-file';
        item.innerHTML = '<span class="labf-file__type">' + TYPE_LABEL[cfg.accept] + '</span>'
          + '<span class="labf-file__name"></span>';
        item.querySelector('.labf-file__name').textContent = f.name;
        item.title = f.url;
        item.addEventListener('click', () => pick(f.url));
        panelList.appendChild(item);
      });
    }

    filesBtn.addEventListener('click', () => {
      const open = panel.style.display !== 'none';
      panel.style.display = open ? 'none' : 'flex';
      if (!open) refresh();
    });

    if (cfg.accept === 'image') uploadBtn.title = 'Bilder komprimeres (AVIF + JPG i 1200/2400 px). Alt-klikk for å laste opp originalen.';
    uploadBtn.addEventListener('click', async (ev) => {
      uploadBtn.disabled = true;
      // Alt-klikk: last opp originalen uten komprimering (Studio 0.7.9+)
      const optimize = !(ev && ev.altKey);
      setStatus(optimize ? 'Velg fil — lastes opp til Labrador…' : 'Velg fil — originalen lastes opp uten komprimering…');
      const unsub = window.faktisk.onLabradorUploadProgress
        ? window.faktisk.onLabradorUploadProgress(msg => {
            progress.style.display = 'block';
            progressBar.style.width = msg.percent + '%';
            setStatus(msg.label || ('Laster opp… ' + msg.percent + '% (' + msg.sentMB + ' av ' + msg.totalMB + ' MB)'));
          })
        : () => {};
      try {
        const res = await window.faktisk.labradorUpload({
          filters: UPLOAD_FILTERS[cfg.accept] || UPLOAD_FILTERS.image,
          optimize,
        });
        if (res.canceled) { setStatus(''); return; }
        if (!res.ok) { setStatus(res.error, true); return; }
        if (res.url && res.optimized && res.stats) {
          const kb = n => n >= 1048576 ? (n / 1048576).toFixed(1).replace('.', ',') + ' MB' : Math.round(n / 1024) + ' KB';
          const st = res.stats;
          setStatus('Komprimert ✓ ' + kb(st.origBytes) + ' → ' + kb(st.fallbackBytes)
            + (st.avifBytes ? ' (AVIF ' + kb(st.avifBytes) + ')' : '') + ' · ' + res.variants.width + ' px'
            + (st.reused ? ' · fantes allerede i Labrador' : ''));
          pick(res.url);
        } else if (res.url) {
          setStatus('Lastet opp «' + res.name + '» ✓');
          pick(res.url);
        } else {
          setStatus(res.note || 'Lastet opp, men fant ikke URL — sjekk «Mine filer».', true);
        }
      } catch (err) {
        setStatus('Opplasting feilet: ' + err.message, true);
      } finally {
        unsub();
        uploadBtn.disabled = false;
        setTimeout(() => { progress.style.display = 'none'; progressBar.style.width = '0%'; }, 2000);
      }
    });
  }

  MOUNTS.forEach(mount);
})();

shared/labrador-status.js:
// Faktisk Studio — Labrador-tilkoblingsstatus i toppbaren (delt fil)
//
// Selvforsynt: injiserer egen CSS og en statusbrikke i .topbar__actions.
// Viser tydelig om Studio er koblet til Labrador (grønn prikk) eller ikke
// (grå prikk + «Koble til»). Klikk kobler til / sjekker på nytt.
// Inkluderes med <script src="shared/labrador-status.js"> etter topbaren
// (i src/ på malsiden). Kanonisk kilde: plugins/_shared/.

(function () {
  'use strict';
  if (!window.faktisk || !window.faktisk.labradorStatus) return;
  const bar = document.querySelector('.topbar__actions');
  if (!bar || document.getElementById('labStatusChip')) return;

  const css = document.createElement('style');
  css.textContent = `
    .lab-chip {
      display: flex; align-items: center; gap: 7px;
      background: rgba(255,255,255,0.12);
      border: 0; border-radius: 18px;
      padding: 6px 14px; margin-right: 6px;
      font-family: var(--font-bold, inherit); font-weight: bold;
      font-size: 12px; color: #fff; cursor: pointer;
      white-space: nowrap;
    }
    .lab-chip:hover { background: rgba(255,255,255,0.24); }
    .lab-chip__dot {
      width: 9px; height: 9px; border-radius: 50%;
      background: #999; flex-shrink: 0;
      transition: background 0.2s;
    }
    .lab-chip.on .lab-chip__dot { background: #2ecc5e; box-shadow: 0 0 6px rgba(46,204,94,0.7); }
    .lab-chip.checking .lab-chip__dot { background: #f5c542; }
  `;
  document.head.appendChild(css);

  const chip = document.createElement('button');
  chip.id = 'labStatusChip';
  chip.className = 'lab-chip checking';
  chip.type = 'button';
  chip.innerHTML = '<span class="lab-chip__dot"></span><span class="lab-chip__label">Labrador…</span>';
  bar.insertBefore(chip, bar.firstChild);
  const label = chip.querySelector('.lab-chip__label');

  let connected = false;
  let busy = false;

  function render(state) {
    chip.classList.remove('on', 'checking');
    if (state === 'on') {
      chip.classList.add('on');
      label.textContent = 'Labrador tilkoblet';
      chip.title = 'Koblet til Labrador — «Mine filer» og opplasting virker i alle verktøy. Klikk for å sjekke på nytt.';
    } else if (state === 'checking') {
      chip.classList.add('checking');
      label.textContent = 'Labrador…';
      chip.title = 'Sjekker Labrador-tilkobling…';
    } else {
      label.textContent = 'Koble til Labrador';
      chip.title = 'Ikke innlogget — klikk for å logge inn. Gjelder alle verktøyene.';
    }
  }

  async function check() {
    if (busy) return;
    render('checking');
    try {
      const st = await window.faktisk.labradorStatus();
      connected = !!st.loggedIn;
    } catch (e) {
      connected = false;
    }
    render(connected ? 'on' : 'off');
  }

  chip.addEventListener('click', async () => {
    if (busy) return;
    busy = true;
    try {
      if (connected) {
        busy = false;
        await check();
        return;
      }
      render('checking');
      label.textContent = 'Logg inn i vinduet…';
      const st = await window.faktisk.labradorConnect();
      connected = !!st.loggedIn;
      render(connected ? 'on' : 'off');
    } catch (e) {
      render('off');
    } finally {
      busy = false;
    }
  });

  window.addEventListener('focus', check);
  check();
})();

shared/new-project.js:
// Delt hjelper: kobler #newProjectBtn til stateClear + reload.
// Plugin må ha en knapp med id="newProjectBtn" i topbaren OG sette
// window.PLUGIN_ID til pluginens id (samme som mappe-navnet i plugins/).
(function () {
  document.addEventListener('DOMContentLoaded', function () {
    var btn = document.getElementById('newProjectBtn');
    if (!btn) return;
    btn.addEventListener('click', async function () {
      try {
        var ok = await window.faktiskDialog.confirm(
          'Slett gjeldende arbeid og start på nytt?\n\nLagrede prosjekter beholdes.',
          true
        );
        if (!ok) return;
        var id = window.PLUGIN_ID || (document.querySelector('meta[name="plugin-id"]') || {}).content;
        if (id && window.faktisk && window.faktisk.stateClear) {
          await window.faktisk.stateClear(id);
        }
        location.reload();
      } catch (e) {
        console.error(e);
      }
    });
  });
})();

